// Lógica de src/phoneNumbers.js

/**
 * Números para la WhatsApp Cloud API.
 *
 * La regla terminó siendo mucho más simple de lo que parecía: **se manda el
 * número tal como llega**, sin corregirle nada. Vale la pena contar por qué,
 * porque el camino equivocado es convincente.
 *
 * Al principio, mandarle a un celular argentino con el 9 de móvil
 * (`5493571684980`, que es exactamente el `wa_id` que entrega el webhook)
 * fallaba con `(#131030) Recipient phone number not in allowed list`, y
 * mandarle sin el 9 (`543571684980`) funcionaba. Probado contra la API real,
 * las dos formas, mismo número. La conclusión parecía obvia: la Cloud API
 * rechaza el 9 argentino, hay que sacarlo.
 *
 * Era falso. Lo que pasaba es que ese número estaba cargado SIN el 9 en la
 * lista de destinatarios de prueba del número de Meta, y esa lista se compara
 * **literal**: `543571684980` y `5493571684980` son dos entradas distintas.
 * Sacarle el 9 acertaba por casualidad.
 *
 * Se vio al probar con un segundo teléfono, cargado solo con el 9: dejaron de
 * funcionar las dos puntas a la vez — no se le podía contestar al cliente ni
 * avisarle al dueño, las dos con el mismo error engañoso sobre la lista.
 *
 * Así que no se toca el número. El `wa_id` es el identificador que Meta mismo
 * usa para esa conversación, y el del dueño lo escribe una persona que está
 * mirando cuál aceptó Meta. Y todo esto es un artefacto del número de prueba:
 * en producción esa lista no existe.
 */

/**
 * Pasa un número al formato del campo `to` de la Cloud API: solo dígitos, sin
 * "+", sin espacios ni guiones. No reinterpreta prefijos.
 *
 * @param {string} numero en cualquier formato (E.164, con espacios, guiones…)
 * @returns {string} solo dígitos; '' si la entrada es basura
 */
function aDestinatario(numero) {
  return String(numero || '').replace(/\D/g, '');
}

// Lógica de src/voiceNotes.js

/**
 * Notas de voz de WhatsApp.
 *
 * Por qué existe: el público de una inmobiliaria manda audios todo el tiempo.
 * Hasta ahora cualquier mensaje que no fuera texto terminaba en
 * `derivar_humano`, así que la mitad de las consultas no las atendía el agente.
 *
 * Cómo funciona: Meta no manda el audio en el webhook, manda un **media ID**.
 * Hay que pedirle a la Graph API la URL de descarga (que caduca a los ~5
 * minutos), bajar el binario con el mismo access token, y mandárselo a Gemini
 * como `inline_data` junto al prompt de clasificación.
 *
 * La ventaja de hacerlo con Gemini y no con un servicio de transcripción
 * aparte: **una sola llamada** devuelve la transcripción, el intent y las
 * entidades. No hay que transcribir primero y clasificar después, ni pagar dos
 * servicios, ni manejar el desfasaje entre ambos.
 *
 * Este módulo es solo la lógica de decisión — qué es un audio, si se puede
 * procesar y por qué no. La descarga la hacen los nodos HTTP del workflow.
 */

// Solo Gemini acepta audio como entrada en la misma llamada que clasifica.
// Anthropic no recibe audio, y Groq lo hace por un endpoint aparte (Whisper),
// lo que sería otra request y otra pieza de configuración.
const PROVEEDORES_CON_AUDIO = ['gemini'];

// Los formatos que acepta Gemini como inline_data. WhatsApp manda las notas de
// voz en OGG/Opus; el resto están para audios reenviados desde otra app.
const MIMES_SOPORTADOS = [
  'audio/ogg',
  'audio/mpeg',
  'audio/mp3',
  'audio/mp4',
  'audio/aac',
  'audio/wav',
  'audio/flac',
  'audio/aiff',
];

// Tope de tamaño del audio. WhatsApp permite hasta 16 MB, pero el base64 infla
// ~33% y todo eso viaja dentro del JSON de la request a Gemini. Por encima de
// esto conviene derivar a un humano antes que arriesgar un 413.
const TAMANIO_MAXIMO_BYTES = 12 * 1024 * 1024;

function soportaAudio(proveedor) {
  return PROVEEDORES_CON_AUDIO.includes(String(proveedor || '').toLowerCase().trim());
}

/**
 * Meta manda el mime con parámetros: "audio/ogg; codecs=opus". Gemini quiere
 * el tipo pelado, sin los parámetros.
 */
function normalizarMime(mime) {
  return String(mime || '')
    .split(';')[0]
    .trim()
    .toLowerCase();
}

function mimeSoportado(mime) {
  return MIMES_SOPORTADOS.includes(normalizarMime(mime));
}

/**
 * Saca los datos del audio de un mensaje del webhook de Meta.
 *
 * @returns {{esAudio: boolean, mediaId: string|null, mime: string|null, esNotaDeVoz: boolean}}
 */
function datosDeAudio(mensajeEntrante) {
  const mensaje = mensajeEntrante || {};
  if (mensaje.type !== 'audio' || !mensaje.audio) {
    return { esAudio: false, mediaId: null, mime: null, esNotaDeVoz: false };
  }

  return {
    esAudio: true,
    mediaId: mensaje.audio.id || null,
    mime: normalizarMime(mensaje.audio.mime_type),
    // Meta distingue la nota de voz grabada en el momento (voice: true) de un
    // archivo de audio adjuntado. Se procesan igual; el dato queda por si
    // después se quiere tratarlos distinto.
    esNotaDeVoz: mensaje.audio.voice === true,
  };
}

/**
 * Por qué este audio no se puede procesar, en un texto que puede leer una
 * persona (termina en el aviso al dueño cuando se deriva).
 *
 * @returns {string|null} null si se puede procesar
 */
function motivoAudioNoProcesable(datos) {
  const { proveedor, mediaId, mime, tamanioBytes } = datos || {};

  if (!mediaId) {
    return 'La nota de voz llegó sin identificador de archivo';
  }
  if (!soportaAudio(proveedor)) {
    return `El proveedor de IA configurado (${proveedor || 'desconocido'}) no procesa audio`;
  }
  if (!mimeSoportado(mime)) {
    return `El formato del audio no está soportado (${normalizarMime(mime) || 'desconocido'})`;
  }
  if (typeof tamanioBytes === 'number' && tamanioBytes > TAMANIO_MAXIMO_BYTES) {
    const mb = (tamanioBytes / 1024 / 1024).toFixed(1);
    return `La nota de voz es demasiado larga (${mb} MB)`;
  }

  return null;
}

/**
 * Texto con el que se representa el audio hasta que el modelo lo transcriba.
 *
 * Hace falta porque el mensaje entrante se guarda en la memoria *antes* de
 * llamar al LLM (para que un segundo mensaje simultáneo lo encuentre), y en
 * ese momento todavía no existe la transcripción. Una vez que vuelve, se
 * reemplaza por el texto real.
 */
const MARCADOR_AUDIO_SIN_TRANSCRIBIR = '(nota de voz)';

/**
 * Pasa a base64 lo que devuelve n8n al pedir el contenido de un binario.
 *
 * Por qué no alcanza con leer `binary.audio.data`: n8n guarda los binarios en
 * disco (modo `filesystem`), y en ese caso ese campo trae el marcador
 * `"filesystem-v2"` en vez del contenido. Mandarlo tal cual a Gemini devuelve
 * un 400 — *Base64 decoding failed for "filesystem-v2"* — que fue exactamente
 * lo que pasó la primera vez que se probó. El contenido real hay que pedirlo
 * con `helpers.getBinaryDataBuffer()`, y lo que vuelve puede ser un Buffer, un
 * Uint8Array o la forma serializada `{type:'Buffer',data:[…]}` según por dónde
 * pase; se contemplan las tres.
 *
 * @returns {string|null} base64 sin prefijo, o null si no hay nada usable
 */
function aBase64(contenido) {
  if (!contenido) return null;

  // Ya viene en base64 (modo de binarios en memoria).
  if (typeof contenido === 'string') return contenido;

  if (typeof Buffer !== 'undefined') {
    if (Buffer.isBuffer(contenido)) return contenido.toString('base64');
    if (contenido.type === 'Buffer' && Array.isArray(contenido.data)) {
      return Buffer.from(contenido.data).toString('base64');
    }
    if (contenido instanceof Uint8Array) return Buffer.from(contenido).toString('base64');
  }

  return null;
}

// <<< END GENERATED >>>

// El WhatsApp Trigger ya nos entrega el "value" del evento de Meta parseado
// (no el body crudo del webhook): trae messaging_product, metadata, contacts
// y messages. El filtro "messageStatusUpdates: []" del trigger ya descarta
// los eventos que son solo actualizaciones de estado (sent/delivered/read),
// así que acá solo deberían llegar mensajes reales.
const entrada = $input.first().json;

// Lectura tolerante de variables de entorno: si la instancia tiene el acceso
// bloqueado (N8N_BLOCK_ENV_ACCESS_IN_NODE=true), el flujo sigue con el default
// en vez de cortarse.
function leerEnv(clave, porDefecto) {
  try {
    return $env[clave] || porDefecto;
  } catch (error) {
    return porDefecto;
  }
}

const mensajeEntrante = (entrada.messages && entrada.messages[0]) || null;
if (!mensajeEntrante) {
  throw new Error('El evento del webhook de Meta no trae un mensaje ("messages"). ¿Llegó un status update en vez de un mensaje entrante?');
}

const telefonoCrudo = String(mensajeEntrante.from || '').trim();
if (!telefonoCrudo) {
  throw new Error('El mensaje de WhatsApp no trae el campo "from". ¿Está bien configurado el webhook en Meta for Developers?');
}

// Meta manda el número sin "+" (ej. "5493511234567"). Lo normalizamos a E.164
// porque el resto del flujo (logs, mensajes al dueño) espera ese formato.
const telefonoCliente = telefonoCrudo.startsWith('+') ? telefonoCrudo : `+${telefonoCrudo}`;

const contacto = (entrada.contacts && entrada.contacts[0]) || {};

const mensaje =
  mensajeEntrante.type === 'text'
    ? String((mensajeEntrante.text && mensajeEntrante.text.body) || '').trim()
    : '';

// Notas de voz: Meta no manda el audio, manda un media ID. Acá solo se decide
// si se puede procesar; la descarga la hacen los dos nodos HTTP que vienen
// después. Ver code/src/voiceNotes.js.
const proveedorLlm = leerEnv('LLM_PROVIDER', 'gemini').toLowerCase();
const audio = datosDeAudio(mensajeEntrante);
const motivoAudio = audio.esAudio
  ? motivoAudioNoProcesable({ proveedor: proveedorLlm, mediaId: audio.mediaId, mime: audio.mime })
  : null;
const audioProcesable = audio.esAudio && motivoAudio === null;

// Un audio que sí se va a procesar NO cuenta como mensaje vacío: el contenido
// está, viaja como audio. Sin esta distinción, "Parse Classification" lo
// derivaría a un humano antes de mirar lo que dijo el modelo.
const mensajeVacio = mensaje.length === 0 && !audioProcesable;

return [
  {
    json: {
      telefonoCliente,
      // Los nodos de salida mandan a estos: el mismo número que llegó, solo
      // en dígitos. No se le corrige el 9 de móvil argentino — ver el porqué
      // en code/src/phoneNumbers.js, que cuenta cómo esa "corrección" rompía
      // la conversación con cualquier teléfono que no fuera el de desarrollo.
      telefonoClienteParaEnvio: aDestinatario(telefonoCliente),
      telefonoDuenoParaEnvio: aDestinatario(leerEnv('OWNER_WHATSAPP_NUMBER', '')),
      nombreCliente: String((contacto.profile && contacto.profile.name) || '').trim() || 'Sin nombre',
      mensaje,
      mensajeVacio,
      // Notas de voz
      esAudio: audio.esAudio,
      esNotaDeVoz: audio.esNotaDeVoz,
      audioMediaId: audio.mediaId,
      audioMime: audio.mime,
      audioProcesable,
      // Se cuenta como motivo de derivación solo si el audio no se puede
      // procesar; si se procesa bien, queda en null.
      motivoAudio,
      messageSid: mensajeEntrante.id || null,
      agencia: leerEnv('AGENCY_NAME', 'la inmobiliaria'),
      // Proveedor del LLM de clasificación: gemini (default, tiene free tier),
      // anthropic o groq. El modelo y la URL son opcionales — si no se
      // configuran, "Build LLM Request" usa el default de cada proveedor.
      proveedorLlm,
      modelo: leerEnv('LLM_MODEL', ''),
      apiUrlLlm: leerEnv('LLM_API_URL', '') || null,
      // Solo aplica a Gemini: minimal | low | medium | high, u "off" para no
      // mandar thinkingConfig (necesario si se apunta a un modelo 2.5).
      nivelThinking: leerEnv('LLM_THINKING_LEVEL', ''),
      recibidoEn: new Date().toISOString(),
    },
  },
];

