    inicio: aRfc3339(cuando),
    fin: aRfc3339(fin),
    zonaHoraria: ZONA_HORARIA,
    resumen: `Visita — ${describirPropiedad(propiedad, datos.propiedad)}`,
    descripcion,
    ubicacion: direccionDe(propiedad),
    invitados: invitado ? [invitado] : [],
    // Ventana para consultar la agenda: el día entero. Recortarla al horario de
    // atención escondería una visita cargada a mano fuera de hora, que ocupa
    // igual al asesor.
    ventanaDia: {
      desde: aRfc3339(conHora(cuando, 0, 0)),
      hasta: aRfc3339(conHora(sumarMinutos(conHora(cuando, 0, 0), 24 * 60), 0, 0)),
    },
    duracionMinutos: duracion,
  };
}

// Lógica de src/sheetValues.js

/**
 * Interpretación de celdas de Google Sheets.
 *
 * Existe porque una planilla no es una base de datos: todo llega como texto y
 * lo escribió una persona. El mismo precio puede venir como `420000`,
 * `420.000`, `$ 420.000` o `USD 52.000`; "tiene cochera" como `sí`, `SI`, `x`
 * o `TRUE`. Nada de eso es culpa de quien carga los datos — es lo que pasa
 * cuando el backend es una planilla, que es justamente lo que la hace usable
 * para una inmobiliaria.
 *
 * La regla es no romper nunca: una celda que no se entiende vale null, y quien
 * llama decide. Un precio ilegible no puede tirar abajo la búsqueda entera.
 *
 * Nombres con sufijo "DeCelda" a propósito: estas funciones se inyectan en los
 * mismos Code nodes que matchProperties.js y calendarEvent.js, que ya tienen
 * sus propios normalizadores. Ver build-workflow.js.
 */

// Formato argentino: el punto separa miles y la coma decimales. Es al revés
// que en JS, así que "420.000" parseado a la ligera da 420.
const SEPARADOR_MILES = /\./g;

const VERDADEROS = new Set(['si', 'sí', 'yes', 'true', 'verdadero', 'x', '1', 'ok', 'tiene']);
const FALSOS = new Set(['no', 'false', 'falso', '0', '-', 'sin']);

// Cualquiera de estos separa los ítems de una celda de lista. Se aceptan
// varios porque nadie va a recordar cuál era el correcto.
const SEPARADORES_DE_LISTA = /[\n|;·•]+/;

function celdaTexto(valor) {
  if (valor === null || valor === undefined) return '';
  return String(valor).trim();
}

/**
 * Número de una celda, tolerando símbolos de moneda, espacios y separadores de
 * miles. Devuelve null si no hay nada numérico que rescatar — incluido el caso
 * de que alguien escriba "dos".
 */
function celdaNumero(valor) {
  if (typeof valor === 'number') return Number.isFinite(valor) ? valor : null;

  const texto = celdaTexto(valor);
  if (!texto) return null;

  // Se toma el primer número que aparezca, en vez de borrar todo lo que no sea
  // dígito: con eso último, "75 m2" daba 752 — el 2 de "m2" se pegaba al
  // final y la propiedad pasaba a tener 752 metros cuadrados.
  const encontrado = texto.match(/-?\d[\d.,]*/);
  if (!encontrado) return null;

  // Una coma o un punto colgando al final no son separadores de nada.
  const limpio = encontrado[0].replace(/[.,]+$/, '');

  const tieneComa = limpio.includes(',');
  // Con coma, ella es el decimal y los puntos son miles. Sin coma, un punto
  // podría ser cualquiera de las dos cosas: "420.000" son cuatrocientos veinte
  // mil, no 420 con 0 decimales, así que se lo trata como miles.
  const normalizado = tieneComa
    ? limpio.replace(SEPARADOR_MILES, '').replace(',', '.')
    : limpio.replace(SEPARADOR_MILES, '');

  const numero = Number(normalizado);
  return Number.isFinite(numero) ? numero : null;
}

/** Entero de una celda; null si no es un entero razonable. */
function celdaEntero(valor) {
  const numero = celdaNumero(valor);
  if (numero === null) return null;
  return Number.isInteger(numero) ? numero : Math.round(numero);
}

/**
 * Booleano de una celda. Una celda vacía es `false`, no null: "no dice que
 * tenga cochera" y "dice que no tiene cochera" dan lo mismo para una búsqueda.
 */
function celdaBooleano(valor) {
  if (typeof valor === 'boolean') return valor;

  const texto = celdaTexto(valor).toLowerCase();
  if (!texto) return false;
  if (VERDADEROS.has(texto)) return true;
  if (FALSOS.has(texto)) return false;

  // Cualquier otro texto se interpreta como que algo hay: "cochera cubierta",
  // "2 cocheras". Lo que no está es lo que se deja vacío.
  return true;
}

/** Lista de una celda, separada por saltos de línea, |, ; o · */
function celdaLista(valor) {
  if (Array.isArray(valor)) return valor.map(celdaTexto).filter(Boolean);

  const texto = celdaTexto(valor);
  if (!texto) return [];

  return texto
    .split(SEPARADORES_DE_LISTA)
    .map((parte) => parte.trim())
    .filter(Boolean);
}

// Páginas que MUESTRAN una imagen pero no la sirven. Es lo que copia cualquiera
// de la barra de direcciones, y no se puede distinguir mirando la URL: tiene
// forma perfecta de link.
//
// Importa más de lo que parece. Meta descarga la imagen desde su servidor: si
// recibe HTML en vez de bytes, igual acepta el envío y devuelve un ID de
// mensaje, y recién después lo descarta en silencio. Nadie se entera — ni el
// cliente, ni la inmobiliaria, ni el log. Y como la propiedad se fue por la
// rama de fotos, tampoco aparece en el texto: desaparece del chat entera.
//
// Por eso se descartan acá: sin foto, la ficha vuelve al mensaje de texto y la
// propiedad se ve igual. Una foto de menos es mucho mejor que una propiedad
// que el cliente nunca supo que existía.
const PAGINAS_QUE_NO_SIRVEN_LA_IMAGEN = [
  /^https?:\/\/(www\.)?unsplash\.com\//i,
  /^https?:\/\/(www\.)?pexels\.com\//i,
  /^https?:\/\/(www\.)?pixabay\.com\//i,
  /^https?:\/\/(www\.)?flickr\.com\//i,
  // Pinterest sirve las imágenes desde otro dominio (pinimg.com), así que acá
  // se puede descartar cualquier subdominio. Unsplash y Pexels no: sus CDN son
  // images.unsplash.com e images.pexels.com, que sí hay que dejar pasar.
  /^https?:\/\/[\w-]*\.?pinterest\.[a-z.]+\//i,
  /^https?:\/\/photos\.google\.com\//i,
  /^https?:\/\/(www\.)?icloud\.com\//i,
];

// Estas sí se pueden arreglar solas, y son las que una inmobiliaria va a usar
// de verdad: el link que copia del botón "Compartir" apunta a la página, pero
// el archivo está a un parámetro de distancia.
const REPARABLES = [
  {
    reconoce: /^https?:\/\/drive\.google\.com\/file\/d\/([^/?#]+)/i,
    arregla: (m) => `https://drive.google.com/uc?export=view&id=${m[1]}`,
  },
  {
    reconoce: /^(https?:\/\/(?:www\.)?dropbox\.com\/[^?#]+)/i,
    arregla: (m) => `${m[1]}?raw=1`,
  },
  {
    // El CDN de Unsplash negocia el formato con quien pide: `auto=format` le
    // sirve AVIF o WebP a cualquiera que los acepte, y WhatsApp solo entiende
    // JPEG y PNG. Meta acepta el envío, descarga un AVIF y descarta el mensaje
    // sin decir nada, igual que con una página HTML.
    //
    // Cuesta encontrarlo porque un `curl` normal recibe JPEG —no manda el
    // Accept que dispara la negociación—, así que la URL parece sana.
    reconoce: /^https?:\/\/images\.unsplash\.com\/[^?#]+/i,
    arregla: (m) => `${m[0]}?w=1080&q=80&fm=jpg`,
  },
];

/**
 * URL de imagen de una celda, o null.
 *
 * Devuelve null tanto si no es una URL ("ver carpeta", una ruta local) como si
 * es una URL que no va a devolver una imagen. Quien llama trata los dos casos
 * igual: la propiedad no tiene foto.
 */
function celdaUrl(valor) {
  const texto = celdaTexto(valor);
  if (!/^https?:\/\/\S+$/i.test(texto)) return null;

  for (const { reconoce, arregla } of REPARABLES) {
    const encontrado = texto.match(reconoce);
    if (encontrado) return arregla(encontrado);
  }

  if (PAGINAS_QUE_NO_SIRVEN_LA_IMAGEN.some((patron) => patron.test(texto))) return null;

  return texto;
}

// Lógica de src/businessConfig.js

/**
 * Los datos del negocio y las preguntas frecuentes, leídos de la planilla.
 *
 * Por qué esto y no solo el catálogo: si el cliente puede cargar sus
 * propiedades pero no puede cambiar su propia comisión ni su horario, la
 * planilla es media configuración y el resto sigue siendo del desarrollador.
 *
 * El horario vive acá y en un solo lugar. Antes estaba repetido en seis: tres
 * constantes que validaban los turnos y cuatro textos que se lo contaban al
 * cliente. Con la planilla de por medio eso deja de ser una molestia y pasa a
 * ser una contradicción — la inmobiliaria cambia a "9 a 20", la FAQ lo dice y
 * el bot igual rechaza un turno a las 19:30. Por eso lo que se carga acá
 * maneja la validación, no solo el texto.
 */


// Lo que estaba fijo en el código hasta ahora. Sigue siendo el default: la
// demo tiene que andar antes de que exista ninguna planilla.
const NEGOCIO_POR_DEFECTO = {
  nombre: 'Inmobiliaria Demo',
  direccion: 'Av. Colón 1250, Alberdi, Córdoba Capital',
  telefono: '',
  logo: null,
  horaApertura: 9,
  horaCierre: 19,
  // null = no se atiende los sábados.
  horaCierreSabado: 13,
};

const DIAS_LABORALES = 'lunes a viernes';

// Alias de las columnas clave/valor de la pestaña "negocio".
const COLUMNA_CLAVE = ['clave', 'campo', 'dato', 'key'];
const COLUMNA_VALOR = ['valor', 'value', 'contenido'];

// Alias de las claves en sí, para que no haya que escribirlas exactas.
const CLAVES = {
  nombre: ['nombre', 'nombre_inmobiliaria', 'agencia'],
  direccion: ['direccion', 'dirección', 'domicilio'],
  telefono: ['telefono', 'teléfono', 'tel', 'whatsapp'],
  logo: ['logo', 'logo_url', 'url_logo'],
  horaApertura: ['hora_apertura', 'apertura', 'abre'],
  horaCierre: ['hora_cierre', 'cierre', 'cierra'],
  horaCierreSabado: ['hora_cierre_sabado', 'hora_cierre_sábado', 'cierre_sabado', 'sabado'],
};

function llave(texto) {
  return String(texto || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .trim();
}

function buscarColumna(fila, alias) {
  const claves = Object.keys(fila || {});
  for (const nombre of alias) {
    const clave = claves.find((k) => llave(k) === llave(nombre));
    if (clave !== undefined) return fila[clave];
  }
  return undefined;
}

/** Las filas clave/valor de la pestaña "negocio" a un mapa plano. */
function aMapa(filas) {
  const mapa = {};

  for (const fila of Array.isArray(filas) ? filas : []) {
    const clave = llave(buscarColumna(fila, COLUMNA_CLAVE));
    if (!clave) continue;
    mapa[clave] = buscarColumna(fila, COLUMNA_VALOR);
  }
  return mapa;
}

function primerValor(mapa, alias) {
  for (const nombre of alias) {
    const valor = mapa[llave(nombre)];
    if (valor !== undefined && celdaTexto(valor) !== '') return valor;
  }
  return undefined;
}

/**
 * Hora de atención válida (0 a 24), o el default. Se acepta "cerrado" para
 * los sábados, que devuelve null.
 */
function aHora(valor, porDefecto) {
  const texto = llave(valor);
  if (texto === 'cerrado' || texto === 'no' || texto === '-') return null;

  const hora = celdaEntero(valor);
  if (hora === null || hora < 0 || hora > 24) return porDefecto;
  return hora;
}

/**
 * @param {Array} filas de la pestaña "negocio"
 * @returns {object} config completa: lo que falte en la planilla usa el default
 */
function parsearNegocio(filas) {
  const mapa = aMapa(filas);
  const texto = (alias, porDefecto) => celdaTexto(primerValor(mapa, alias)) || porDefecto;

  const apertura = aHora(primerValor(mapa, CLAVES.horaApertura), NEGOCIO_POR_DEFECTO.horaApertura);
  const cierre = aHora(primerValor(mapa, CLAVES.horaCierre), NEGOCIO_POR_DEFECTO.horaCierre);

  return {
    nombre: texto(CLAVES.nombre, NEGOCIO_POR_DEFECTO.nombre),
    direccion: texto(CLAVES.direccion, NEGOCIO_POR_DEFECTO.direccion),
    telefono: texto(CLAVES.telefono, NEGOCIO_POR_DEFECTO.telefono),
    logo: texto(CLAVES.logo, '') || null,
    // Un cierre antes de la apertura dejaría la agencia sin ningún horario
    // válido y el bot rechazaría todos los turnos sin poder explicar por qué.
    horaApertura: apertura === null ? NEGOCIO_POR_DEFECTO.horaApertura : apertura,
    horaCierre: cierre === null || cierre <= apertura ? NEGOCIO_POR_DEFECTO.horaCierre : cierre,
    horaCierreSabado: aHora(primerValor(mapa, CLAVES.horaCierreSabado), NEGOCIO_POR_DEFECTO.horaCierreSabado),
  };
}

/** El horario como se lo cuenta al cliente, desde los mismos números que validan. */
function describirHorarios(negocio) {
  const config = negocio || NEGOCIO_POR_DEFECTO;
  const semana = `*${DIAS_LABORALES} de ${config.horaApertura} a ${config.horaCierre} hs*`;

  if (!config.horaCierreSabado) return semana;
  return `${semana} y los *sábados de ${config.horaApertura} a ${config.horaCierreSabado} hs*`;
}

/**
 * Completa {{nombre}}, {{direccion}}, {{telefono}} y {{horarios}} dentro de un
 * texto de la planilla. Es lo que hace que cambiar el horario en una celda se
 * propague a todas las respuestas que lo mencionan.
 *
 * Un placeholder desconocido se deja como está: es más fácil de ver en el chat
 * que un hueco en blanco, y le dice al cliente que se equivocó en el nombre.
 */
function resolverPlaceholders(texto, negocio) {
  const config = negocio || NEGOCIO_POR_DEFECTO;
  const valores = {
    nombre: config.nombre,
    direccion: config.direccion,
    telefono: config.telefono,
    horarios: describirHorarios(config),
  };

  return String(texto || '').replace(/\{\{\s*(\w+)\s*\}\}/g, (original, clave) => {
    const valor = valores[llave(clave)];
    return valor === undefined || valor === '' ? original : valor;
  });
}

/**
 * Las filas de la pestaña "faq" a entradas como las que espera answerFaq.
 * Se descarta lo que no tenga respuesta: una entrada vacía solo sirve para que
 * el bot conteste con un silencio.
 */
function parsearFaq(filas) {
  const entradas = [];

  for (const fila of Array.isArray(filas) ? filas : []) {
    const id = celdaTexto(buscarColumna(fila, ['id', 'clave', 'tema']));
    const respuesta = celdaTexto(buscarColumna(fila, ['respuesta', 'texto', 'contenido']));
    if (!id || !respuesta) continue;

    entradas.push({
      id,
      pregunta: celdaTexto(buscarColumna(fila, ['pregunta', 'consulta'])),
      claves: celdaTexto(buscarColumna(fila, ['claves', 'palabras_clave', 'keywords']))
        .split(/[,\n|;]+/)
        .map((c) => c.trim())
        .filter(Boolean),
      respuesta,
    });
  }

  return entradas;
}

// Lógica de src/scheduling.js

/**
 * Validación y registro de visitas a propiedades.
 *
 * La fecha y la hora llegan ya extraídas por el clasificador (Claude las
 * devuelve como `fecha_visita` en formato YYYY-MM-DD y `hora_visita` en HH:MM).
 * Acá se valida que sean reales, futuras y dentro del horario de atención.
 *
 * Lo que sí se pide, si no vino, es QUÉ propiedad quiere ver: sin eso el dueño
 * recibe un turno sin saber qué mostrar ni adónde ir. Y como el cliente puede
 * no haber elegido todavía, la pregunta ofrece mostrarle el catálogo — que es
 * de lo que vino a hablar.
 *
 * El mail, en cambio, es opcional. La invitación de Google viaja por mail y de
 * WhatsApp solo tenemos el teléfono, pero el cliente ya recibe su confirmación
 * por el chat: pedírselo agrega un ida y vuelta para darle algo que ya tiene, y
 * bloquear la reserva por no tenerlo sería lo peor de los dos mundos. Si lo
 * menciona, se lo invita; si no, se agenda igual.
 *
 * `ahora` se recibe por parámetro en vez de llamar a new Date() adentro, para
 * que los tests sean determinísticos. Quien llama le pasa la hora de pared de
 * Córdoba (ver localTime.js), no la del proceso.
 */


// Los valores por defecto siguen acá para que todo ande sin planilla, pero el
// horario real sale de la pestaña "negocio". No puede estar en dos lugares:
// si la inmobiliaria pone "9 a 20" en su planilla y estas constantes siguen
// diciendo 19, el bot le contesta un horario y le rechaza otro.
const HORA_APERTURA = NEGOCIO_POR_DEFECTO.horaApertura;
const HORA_CIERRE = NEGOCIO_POR_DEFECTO.horaCierre;
const SABADO_CIERRE = NEGOCIO_POR_DEFECTO.horaCierreSabado;

const DIAS = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
const MESES = [
  'enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio',
  'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre',
];

function parsearFecha(valor) {
  if (typeof valor !== 'string') return null;
  const match = valor.trim().match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return null;

  const [, anio, mes, dia] = match.map(Number);
  const fecha = new Date(anio, mes - 1, dia);
  // Rechaza fechas tipo 2026-02-31, que Date "corrige" silenciosamente.
  if (fecha.getFullYear() !== anio || fecha.getMonth() !== mes - 1 || fecha.getDate() !== dia) {
    return null;
  }
  return { anio, mes, dia };
}

function parsearHora(valor) {
  if (typeof valor !== 'string') return null;
  const match = valor.trim().match(/^(\d{1,2}):(\d{2})$/);
  if (!match) return null;

  const horas = Number(match[1]);
  const minutos = Number(match[2]);
  if (horas < 0 || horas > 23 || minutos < 0 || minutos > 59) return null;
  return { horas, minutos };
}

/**
 * A qué hora cierra ese día, o null si no se atiende.
 *
 * @param {number} diaSemana  0 = domingo
 * @param {object} [negocio]  config de la planilla; sin ella, los defaults
 */
function cierreDelDia(diaSemana, negocio) {
  const config = negocio || NEGOCIO_POR_DEFECTO;
  if (diaSemana === 0) return null; // domingo cerrado
  return diaSemana === 6 ? config.horaCierreSabado : config.horaCierre;
}

function formatearFechaLegible(cuando) {
  return `${DIAS[cuando.getDay()]} ${cuando.getDate()} de ${MESES[cuando.getMonth()]}`;
}

function formatearHoraLegible(cuando) {
  const minutos = String(cuando.getMinutes()).padStart(2, '0');
  return `${cuando.getHours()}:${minutos}`;
}

/**
 * @param {object} entidades  { fecha_visita, hora_visita, email, referencia_propiedad }
 * @param {{ahora?: Date|string}} opciones
 * @returns {{valido: boolean, motivo: string, cuando: Date|null, faltante: string[]}}
 */
function parseVisitRequest(entidades, opciones) {
  const datos = entidades && typeof entidades === 'object' ? entidades : {};
  const config = (opciones && opciones.negocio) || NEGOCIO_POR_DEFECTO;
  const ahora = opciones && opciones.ahora ? new Date(opciones.ahora) : new Date();

  const fecha = parsearFecha(datos.fecha_visita);
  const hora = parsearHora(datos.hora_visita);
  const sinPropiedad = String(datos.referencia_propiedad || '').trim().length === 0;

  const faltante = [];
  if (!fecha) faltante.push('fecha');
  if (!hora) faltante.push('hora');
  if (faltante.length > 0) {
    // Si además no sabemos qué quiere ver, se avisa acá mismo en vez de
    // preguntarlo en el mensaje siguiente: son dos datos que el cliente tiene
    // igual de a mano, y encadenar preguntas de a una cansa.
    return { valido: false, motivo: 'datos_incompletos', cuando: null, faltante, sinPropiedad };
  }

  const cuando = new Date(fecha.anio, fecha.mes - 1, fecha.dia, hora.horas, hora.minutos);

  if (cuando.getTime() <= ahora.getTime()) {
    return { valido: false, motivo: 'fecha_pasada', cuando, faltante: ['fecha'] };
  }

  const cierre = cierreDelDia(cuando.getDay(), config);
  if (cierre === null) {
    // Qué día está cerrado depende de la planilla: el domingo siempre, y el
    // sábado si la inmobiliaria puso "cerrado". El mensaje tiene que nombrar
    // el día correcto, no dar por sentado que es domingo.
    return { valido: false, motivo: 'dia_cerrado', cuando, faltante: ['fecha'], dia: DIAS[cuando.getDay()] };
  }
  if (hora.horas < config.horaApertura || hora.horas >= cierre) {
    return { valido: false, motivo: 'fuera_de_horario', cuando, faltante: ['hora'] };
  }

  // Recién acá, con el horario ya validado: no tiene sentido preguntar qué
  // quiere ver para un turno que se va a rechazar igual.
  if (sinPropiedad) {
    return { valido: false, motivo: 'falta_propiedad', cuando, faltante: ['propiedad'] };
  }

  return { valido: true, motivo: 'ok', cuando, faltante: [] };
}

/**
 * Marca la visita como imposible porque la agenda ya tiene ese horario tomado.
 * No lo decide parseVisitRequest porque depende de la agenda real, que se
 * consulta después; el resultado tiene la misma forma para que el resto del
 * flujo no distinga entre "no se puede por horario" y "no se puede por agenda".
 *
 * @param {object} validacion   la validación original, ya válida
 * @param {string[]} alternativas horarios libres, formato "HH:MM"
 */
function marcarHorarioOcupado(validacion, alternativas) {
  return {
    ...validacion,
    valido: false,
    motivo: 'horario_ocupado',
    faltante: ['hora'],
    alternativas: Array.isArray(alternativas) ? alternativas : [],
  };
}

/**
 * Fila que se guarda en el registro de visitas.
 *
 * @param {object} [propiedad] la del catálogo, si se pudo identificar. Cambia
 *        qué se guarda y cómo se la nombra: el cliente dijo "el de Las Flores"
 *        y el registro tiene que decir INM-101, pero el mensaje de vuelta no
 *        puede contestarle con un código que él nunca usó.
 */
function buildVisitRecord(validacion, contacto, entidades, propiedad) {
  const datos = entidades && typeof entidades === 'object' ? entidades : {};
