// Lo que entra son los bloques ocupados que devolvió Calendar, no la visita:
// esa hay que ir a buscarla al nodo que la validó.
const visita = $('Validate Visit Request').first().json;

// La config del cliente: catálogo, datos del negocio y FAQ, leídos de su
// planilla (o del respaldo del repo si Sheets no contestó).
const config = $('Config Ready').first().json.config || {};
const negocio = config.negocio || NEGOCIO_POR_DEFECTO;
const filas = $input.all().map((entrada) => entrada.json || {});

// Si la consulta falló, el nodo emite un item con `error` en vez de bloques.
// En ese caso se sigue como si estuviera libre: negarse a agendar porque no se
// pudo leer la agenda es peor para el cliente que un solapamiento eventual, y
// si Calendar está caído el nodo que crea el evento va a fallar también — el
// mensaje ya contempla ese caso y no promete ninguna invitación.
const consultaFallada = filas.some((fila) => typeof fila.error === 'string');
const ocupados = consultaFallada ? [] : bloquesOcupados(filas);

const cuando = deRfc3339(visita.registro.fechaIso);
const duracionMinutos = (visita.evento && visita.evento.duracionMinutos) || DURACION_VISITA_MINUTOS;
const ocupado = seSolapa(ocupados, cuando, sumarMinutos(cuando, duracionMinutos));

// Las alternativas se calculan solo si hacen falta: es recorrer la jornada
// entera hueco por hueco.
const alternativas = ocupado
  ? formatearAlternativas(
      buscarAlternativas(ocupados, cuando, {
        apertura: negocio.horaApertura,
        cierre: cierreDelDia(cuando.getDay(), negocio),
        duracionMinutos,
        ahora: ahoraEnArgentina(),
      }),
    )
  : [];

return [
  {
    json: {
      ...visita,
      validacion: ocupado ? marcarHorarioOcupado(visita.validacion, alternativas) : visita.validacion,
      // Para poder ver desde la ejecución por qué se aceptó o se rechazó.
      bloquesOcupadosEnElDia: ocupados.length,
      consultaCalendarFallada: consultaFallada,
    },
  },
];
